#!/usr/bin/env node
/**
 * Permits cleartext HTTP for the Home Library feature in release Android builds.
 *
 * The Home Library connects to a desktop host over plain http:// on the local network
 * (src/services/lanHome/protocol.ts). Android blocks cleartext by default, and the
 * generated Gradle project sets usesCleartextTraffic = "false" for everything except
 * `debug` -- so PC-hosted library sync works in a dev build and silently fails in a
 * release one, while desktop is unaffected. That is exactly the bug this fixes.
 *
 * src-tauri/gen/ is gitignored and regenerated by `tauri android init`, so the fix can
 * not live there: run this after generating the Android project and before building a
 * release APK. Safe to run repeatedly.
 */
import { readFileSync, writeFileSync, existsSync } from 'node:fs';

const path = process.argv[2] ?? 'src-tauri/gen/android/app/build.gradle.kts';
if (!existsSync(path)) {
  console.error(`No generated Gradle project at ${path}. Run "tauri android init" first.`);
  process.exit(1);
}

const src = readFileSync(path, 'utf8');
if (src.includes('HOME_LIBRARY_CLEARTEXT')) {
  console.log('already patched');
  process.exit(0);
}

const anchor = 'manifestPlaceholders["usesCleartextTraffic"] = "false"';
if (!src.includes(anchor)) {
  console.error('Could not find the usesCleartextTraffic placeholder; the Gradle template changed.');
  process.exit(1);
}

const replacement = [
  '// HOME_LIBRARY_CLEARTEXT: the Home Library talks http:// to a LAN desktop host.',
  '        // Android blocks cleartext in release builds, which made PC-hosted library sync',
  '        // fail on Android only, while desktop was unaffected.',
  '        // See scripts/patch-android-cleartext.mjs.',
  '        manifestPlaceholders["usesCleartextTraffic"] = "true"',
].join('\n');

writeFileSync(path, src.replace(anchor, replacement));
console.log(`patched ${path}`);
